from rest_framework import viewsets, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response
from django_fsm import can_proceed
from .models import PublishedArticle

class EditorialArticleViewSet(viewsets.ModelViewSet):
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return PublishedArticle.objects.filter(publication=self.request.user.publication)

    @action(detail=True, methods=['post'])
    def revert_to_draft(self, request, pk=None):
        article = self.get_object()
        if not can_proceed(article.revert_to_draft):
            return Response({'error': 'Cannot revert article to draft'}, status=status.HTTP_400_BAD_REQUEST)

        article.revert_to_draft()
        article.save()
        return Response({'status': 'reverted', 'article_id': article.id, 'state': article.state})
